// Selecciona la fila pendiente con mayor prioridad. Si no hay, devuelve vacío.
const rows = $input.all().map(i => i.json);
const priorityRank = { alta: 3, media: 2, baja: 1 };
const pending = rows
  .filter(r => (r.estado || '').toLowerCase() === 'pendiente')
  .sort((a, b) => {
    const pa = priorityRank[(a.prioridad || '').toLowerCase()] || 0;
    const pb = priorityRank[(b.prioridad || '').toLowerCase()] || 0;
    if (pb !== pa) return pb - pa;
    return Number(a.id || 0) - Number(b.id || 0);
  });
if (pending.length === 0) return [];
const row = pending[0];
return [{ json: row }];

// Extrae top 5 URLs orgánicas con sus title/snippet y deja todo en un único item.
const serp = $input.first().json;
const row = $('Pick Top Pending').item.json;
const organic = (serp.organic || []).slice(0, 5).map((r, i) => ({
  pos: r.position || i + 1,
  title: r.title || '',
  url: r.link || '',
  snippet: r.snippet || ''
}));
return [{
  json: {
    row,
    serp_summary: organic
      .map(o => `${o.pos}. ${o.title}\n   ${o.url}\n   ${o.snippet}`)
      .join('\n\n'),
    serp_top: organic
  }
}];

