// Extrae el JSON del artículo de la respuesta del modelo. Claude a veces devuelve
// el JSON entre ```json ... ``` o con texto explicativo alrededor. Tolerante.
const raw = $input.first().json;
const text = raw.message?.content?.[0]?.text || raw.content?.[0]?.text || raw.text || JSON.stringify(raw);
let jsonStr = text.trim();
// Strip code fences
const fenceMatch = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
if (fenceMatch) jsonStr = fenceMatch[1].trim();
// Find first { to last } if there's text around
const first = jsonStr.indexOf('{');
const last = jsonStr.lastIndexOf('}');
if (first !== -1 && last !== -1) jsonStr = jsonStr.slice(first, last + 1);
let article;
try {
  article = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('Article JSON parse failed: ' + e.message + '\nFirst 300 chars: ' + jsonStr.slice(0, 300));
}
// SIEMPRE sobrescribimos publishedAt y updatedAt con la fecha real de n8n.
// Claude inventa fechas (no conoce "ahora"); sin este fix, los artículos
// generados quedan enterrados en el listado por orden de publishedAt DESC.
const nowIso = new Date().toISOString();
article.publishedAt = nowIso;
article.updatedAt = nowIso;
// Validation mínima
if (!article.id || !article.slug?.es || !article.slug?.en || !article.content?.es?.length) {
  throw new Error('Article shape invalid: missing required fields');
}
const row = $('Pick Top Pending').item.json;
return [{ json: { article, row } }];

